    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    position: relative;
    width: 185px;
    height: 110px;
    margin: 30px auto;
}

.softlite-rectangle-input {
    position: absolute;
    width: 120px;
    text-align: center;
}

.softlite-top-input {
    top: -16px;
    left: 50%;
    transform: translateX(-50%);
}

.softlite-bottom-input {
    bottom: -30px;
    left: 50%;
    transform: translateX(-50%);
}

