    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    height: 100%;
}

.softlite-side-input {
    width: 100px;
}

.softlite-left-input {
    left: -34px;
    top: 50%;
    transform: translateY(-50%);
}

.softlite-right-input {
    right: -34px;
    top: 50%;
    transform: translateY(-50%);
}

.softlite-rectangle {
    flex-grow: 1;
    border: 1px solid #000;
    height: 100%;
    margin: 0 15px;
}

.softlite-text-center input{
    text-align: center;
